      "overview": "‘우연’과 ‘인연’이 만들어낸 기적을 일상에 녹여낸, '예천국제스마트폰영화제' 4편의 단편 수상작. [알마티] 영화를 찍기 위해 낯선 나라 카자흐스탄의 알마티에 머물던 정우, 그러다 뜻밖에도 곤란한 상황에 처하게 되고, 그런 그를 현지 고려인 안젤리카가 돕는다. 고요한 자연, 바람, 불빛 그리고 도심 속 잔잔한 말과 침묵 속 감정들이 두 청춘에게 서서히 스며든다. [스치기만 해도 치명타] 가장으로서 동생을 부양하며 죽집을 운영하는 현지. 9급 공무원 탈출을 꿈꾸며 현지네 가게에서 저녁 아르바이트를 하는 하온. 3분 뒤면 퇴근이다! 고단한 하루의 끝을 앞두고 있던 순간 누군가가 죽집의 문을 열어젖히는데... [스치는 인연으로 통한다] 나른한 평일 저녁. 누군가는 퇴근길에 치킨을 시키고, 누군가는 그 치킨집에서 아르바이트를 한다. 용돈을 벌기 위해 퇴근길 배달을 뛰는 사람도 있고, 누군가는 생을 마감하려 한다. 그 모든 스치는 인연들이 날실과 씨실처럼 얽힌다. [그때의 우리] 오디션장에서 전 연인을 만났다. 감독의 코멘트에 따라 다시 한번 커플로 호흡을 맞추는데… 그때의 우리도 지금 대본 속의 캐릭터처럼 서로를 조금만 더 배려했다면 어땠을까? 연기는 점차 진심이 되어 간다.",
